<script setup lang="ts">
import { computed, ref, type UnwrapNestedRefs } from 'vue';
import { NAlert, NButton, NForm, NFormItem, NInput, NInputNumber, NModal, NSelect, NSpace, type FormInst, type FormRules } from 'naive-ui';
import type { useWorkbench } from '../../app/useWorkbench';
const { w } = defineProps<{ w: UnwrapNestedRefs<ReturnType<typeof useWorkbench>> }>();
const form = ref<FormInst | null>(null);
const rules = computed<FormRules>(() => w.workspaceAction === 'create' ? { newWorkspaceName: { required: true, whitespace: true, message: '请输入工作区名称', trigger: ['blur', 'input'] } } : w.workspaceAction === 'invite' ? { inviteHours: { type: 'number', required: true, min: 1, max: 168, message: '有效期应为 1 至 168 小时', trigger: 'change' } } : { inviteInput: { required: true, whitespace: true, message: '请输入邀请链接或邀请码', trigger: ['blur', 'input'] } });
async function submit() { if (w.busy) return; try { await form.value?.validate(); } catch { return; } if (w.workspaceAction === 'create') await w.createWorkspace(); else if (w.workspaceAction === 'invite') await w.createInvitation(); else await w.inspectInput(); }
</script>
<template>
  <NModal :show="!!w.workspaceAction" preset="card" class="workspace-dialog" :title="w.dialogTitle" :closable="!w.busy" :mask-closable="!w.busy" :close-on-esc="!w.busy" :style="{ width: '480px', maxWidth: 'calc(100vw - 32px)' }" :aria-busy="w.busy" @update:show="value => { if (!value) w.closeWorkspaceDialog(); }">
    <NAlert v-if="w.error" type="error" role="alert" class="section-feedback">{{ w.error }}</NAlert>
    <template v-if="w.workspaceAction === 'create'"><p class="muted">新空间独立管理成员和数字员工，不改变你在现有空间的角色。</p><NForm ref="form" :model="w" :rules="rules" @submit.prevent="submit"><NFormItem label="工作区名称" path="newWorkspaceName"><NInput v-model:value="w.newWorkspaceName" :disabled="w.busy" :maxlength="100" placeholder="新工作区名称" :input-props="{ id: 'new-workspace', 'aria-label': '新工作区名称' }" /></NFormItem><NButton block type="primary" attr-type="submit" :loading="w.busy" :disabled="w.busy">创建工作区</NButton></NForm></template>
    <template v-else-if="w.workspaceAction === 'invite' && w.canManage"><NForm ref="form" :model="w" :rules="rules" @submit.prevent="submit"><NFormItem label="受邀角色"><NSelect v-model:value="w.inviteRole" :disabled="w.busy" aria-label="受邀角色" filterable :input-props="{ 'aria-label': '受邀角色' }" :options="[{ label: '成员', value: 'member' }, ...(w.selected?.role === 'owner' ? [{ label: '管理员', value: 'admin' }] : [])]" /></NFormItem><NFormItem label="有效期（小时）" path="inviteHours"><NInputNumber v-model:value="w.inviteHours" :disabled="w.busy" :input-props="{ 'aria-label': '有效期（小时）' }" :min="1" :max="168" :precision="0" :show-button="true" /></NFormItem><NButton block type="primary" attr-type="submit" :loading="w.busy" :disabled="w.busy">生成单次邀请链接</NButton></NForm><div v-if="w.generatedInvite" class="invite-result"><NFormItem label="邀请链接"><NInput :value="w.generatedInvite.link" readonly :input-props="{ 'aria-label': '邀请链接' }" /></NFormItem><p class="field-note">有效期至 {{ w.formatTime(w.generatedInvite.expiresAt) }}。请手动复制给受邀人，勿公开传播。关闭窗口、切换工作区或退出后不再显示。</p></div></template>
    <template v-else-if="w.workspaceAction === 'join'">
      <template v-if="!w.invitationToken"><p class="muted">粘贴邀请链接或邀请码，先核对工作区和角色再加入。</p><NForm ref="form" :model="w" :rules="rules" @submit.prevent="submit"><NFormItem label="邀请链接或邀请码" path="inviteInput"><NInput v-model:value="w.inviteInput" :disabled="w.busy" placeholder="邀请链接或邀请码" :input-props="{ id: 'invitation-input', autocomplete: 'off', 'aria-label': '邀请链接或邀请码' }" /></NFormItem><NButton block type="primary" attr-type="submit" :loading="w.busy" :disabled="w.busy">查看邀请</NButton></NForm></template>
      <template v-else><template v-if="w.invitation"><NAlert type="info" title="核对邀请信息">受邀加入 {{ w.invitation.workspace.name }}，角色：{{ w.roleLabel(w.invitation.role) }}。<br />有效期至 {{ w.formatTime(w.invitation.expiresAt) }}。邀请仅限一次使用。</NAlert><template v-if="w.user"><p>将使用当前账号 @{{ w.user.username }} 加入。若账号不对，请先保留原邀请链接，再关闭窗口并退出登录；切换账号后重新打开原链接。</p><NButton type="primary" block :loading="w.busy" :disabled="w.busy" @click="w.acceptInvitation">确认接受邀请</NButton></template><template v-else><p class="muted">已有账号请登录后确认加入；新账号注册后直接加入，不额外创建工作区。</p><NButton type="primary" :disabled="w.busy" @click="w.workspaceAction = null">继续登录或注册</NButton></template></template><template v-else><p>尚未确认邀请有效性，不会自动改为普通注册。</p><NButton :disabled="w.busy" @click="w.run(w.inspectInvitation)">重新检查邀请</NButton></template><NSpace class="section-feedback"><NButton quaternary :disabled="w.busy" @click="w.cancelInvitation">使用其他邀请</NButton></NSpace></template>
    </template>
    <p v-if="w.busy" class="field-note" role="status">正在处理，请稍候；完成后可关闭窗口。</p>
    <template #footer><NSpace justify="end"><NButton :disabled="w.busy" aria-label="关闭窗口" @click="w.closeWorkspaceDialog()">关闭</NButton></NSpace></template>
  </NModal>
</template>
